"""Shared lifecycle APIs for Blender resources generated by Driver Espresso.

Feature modules describe the resources they need; this package gives those
resources stable identity, ownership and cleanup semantics.  Importing it has
no Blender registration side effects.
"""

from importlib import import_module


_MODULES = {
    "contracts": ".core.contracts",
    "registry": ".core.registry",
    "transaction": ".core.transaction",
    "animation": ".resources.animation",
    "attachments": ".resources.attachments",
    "helpers": ".resources.helpers",
    "properties": ".resources.properties",
    "clear_snapshot": ".resources.clear_snapshot",
}

__all__ = tuple(_MODULES)


def __getattr__(name):
    module_path = _MODULES.get(name)
    if module_path is None:
        raise AttributeError("module %r has no attribute %r" % (__name__, name))
    module = import_module(module_path, __name__)
    globals()[name] = module
    return module
